options.script:
// Step 1: Reshape Grafana fields into a plain object
function extractFields(series) {
  return Object.fromEntries(series.fields.map(f => [f.name, Array.from(f.values)]));
}

// Step 2: Replace GNSS values with RINEX prefixes (in-place)
function mapGnssPrefixes(fields) {
  const prefixMap = {
    GPS: 'G', GLO: 'R', GAL: 'E', BDS: 'C',
    QZSS: 'J', NAVIC: 'I', SBAS: 'S'
  };
  fields.gnss = fields.gnss.map(g => prefixMap[g] ?? g);
  return fields;
}

// Step 3: Group all rows by GNSS prefix
function groupByGnss(fields) {
  const groups = {};
  for (let i = 0; i < fields.gnss.length; i++) {
    const key = fields.gnss[i];
    if (!groups[key]) {
      groups[key] = Object.fromEntries(Object.keys(fields).map(f => [f, []]));
    }
    for (const [f, values] of Object.entries(fields)) {
      groups[key][f].push(values[i]);
    }
  }
  return groups;
}

// Step 4: Create one Plotly trace per GNSS group
function makeTraces(groups) {
  const colorMap = {
    G: 'blue', R: 'magenta', E: 'green', C: 'red',
    J: 'orange', I: 'yellow', S: 'blue'
  };

  return Object.entries(groups).map(([gnss, group]) => ({
    type: 'scatterpolar',
    mode: 'markers+text',
    name: gnss,
    theta: group.azimuth,
    r: group.elevation,
    text: group.gnss.map((prefix, i) => prefix + group.sv[i]),
    textposition: 'top center',
    marker: {
      size: 8,
      color: colorMap[gnss] ?? 'black'
    }
  }));
}

// Main entry point
if (!data.series.length) return { data: [] };

return {
  data: makeTraces(
    groupByGnss(
      mapGnssPrefixes(
        extractFields(data.series[0])
      )
    )
  )
};
